  { instructions: "差分はどの種類の変更を含むか。", output: BOOL("種類がある。", "種類がない。") },
  "種類の選択を boolean で表そうとしている。");
defect("QSM004", "eval2_count_boolean", "en", "eval2",
  { instructions: "How many files does the change touch?", output: BOOL("It touches files.", "It touches none.") },
  "数量を boolean では記録できない。");
defect("QSM004", "eval2_unordered_ordinal", "ja", "eval2",
  { instructions: "変更の種類を判定する。", output: ORD("kind", ["バグ修正", "機能追加", "リファクタリング"]) },
  "順序のない種類を ordinal として宣言している。");
legit("QSM004", "eval2_boolean_scope", "ja", "eval2",
  { instructions: "差分に、依頼で許可されていない変更が含まれるか。", output: BOOL("許可されていない変更が含まれる。", "許可された範囲に収まっている。") },
  "yes/no の判断に boolean が合っている。");

defect("QBE004", "eval2_relative_ja", "ja", "eval2",
  { instructions: "この変更の影響を段階評価する。", output: ORD("impact", ["影響なし", "軽微（上の段階より大きい）", "重大（さらに大きい）"]) },
  "レベルが相対的な大小で記述されている。",
  { evidencePointer: "/questions/0/output" });
defect("QBE004", "eval2_previous_en", "en", "eval2",
  { instructions: "Rate the impact of this change.", output: ORD("impact", ["No change", "More than the previous level", "The most"]) },
  "Levels rely on the previous level for meaning.",
  { evidencePointer: "/questions/0/output" });
defect("QBE004", "eval2_rank_relative", "ja", "eval2",
  { instructions: "この変更をランク付けする。", output: ORD("rank", ["Aランク", "Bランク（Aより下）", "Cランク（Bより下）"]) },
  "ランクの説明が他ランクとの比較でしか成立しない。",
  { evidencePointer: "/questions/0/output" });
legit("QBE004", "eval2_self_contained_status", "ja", "eval2",
  { instructions: "この作業の状態を評価する。", output: ORD("status", ["未着手で作業は始まっていない", "作業中だが未完了", "完了して検証済み"]) },
  "各レベルが単独で状況を記述している。");

export const corpus = cases;
export const corpusSummary = {
  total: cases.length,
  defect: cases.filter(item => item.kind === "defect").length,
  legitimate: cases.filter(item => item.kind === "legitimate").length,
  tuning: cases.filter(item => item.split === "tuning").length,
  eval: cases.filter(item => item.split === "eval").length,
  eval2: cases.filter(item => item.split === "eval2").length,
  languages: ["ja", "en"],
  families: ["QSM001", "QSM002", "QSM003", "QSM004", "QBE004"],
};

state.run_corpus_mjs:
/**
 * Runs the screening evaluation corpus and computes the section-4 metrics:
 * per-rule precision/recall/unknown, legitimate-stop rate, evidence-span
 * correctness, usage, latency, and execution failures. Metrics are reported
 * overall and separately for the tuning and eval splits.
 *
 * Usage:
 *   node evaluation/run-corpus.mjs --live [--model jev-latest] [--record evaluation/recorded-live.jsonl]
 *   node evaluation/run-corpus.mjs --replay evaluation/recorded-live.jsonl [--out evaluation/results.json]
 *
 * Live mode reads TYPESAFE_CREDENTIAL_ENV from the environment and sends one request
 * per case (the corpus is 60 cases). Nothing is retried automatically.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { buildScreeningRequests, screenFromRecordings, screenLive } from "../dist/screening.js";
import { createHttpTransport } from "../dist/transport.js";
import { loadCases, validateCases } from "./validate-cases.mjs";

const root = new URL("../", import.meta.url);
const pack = JSON.parse(readFileSync(new URL("rules/screening-pack.json", root), "utf8"));
const version = JSON.parse(readFileSync(new URL("package.json", root), "utf8")).version;

const { values } = parseArgs({
  options: {
    live: { type: "boolean", default: false },
    replay: { type: "string" },
    out: { type: "string", default: "evaluation/results.json" },
    record: { type: "string", default: "evaluation/recorded-live.jsonl" },
    model: { type: "string" },
    split: { type: "string", default: "all" },
  },
});

if (!["all", "tuning", "eval", "eval2"].includes(values.split)) {
  console.error("--split must be all, tuning, eval, or eval2");
  process.exit(2);
}

const allCases = loadCases();
const problems = validateCases(allCases);
if (problems.length > 0) {
  for (const problem of problems) console.error(`case validation: ${problem}`);
  process.exit(2);
}
const cases = values.split === "all" ? allCases : allCases.filter(item => item.split === values.split);

const classifyCase = (item, report) => {
  const diagnostics = report.diagnostics;
  const observation = ruleId => report.observations.find(entry => entry.ruleId === ruleId);
  if (item.kind === "legitimate") {
    const stopped = diagnostics.length > 0;
    return {
      caseId: item.caseId,
      family: item.family,
      split: item.split,
      outcome: stopped ? "stopped" : "clean",
      signalRules: diagnostics.map(diagnostic => diagnostic.ruleId),
      unknownRules: report.observations
        .filter(entry => ["inconclusive", "not_applicable", "not_run", "malformed", "backend_error"].includes(entry.status))
        .map(entry => entry.ruleId),
    };
  }
  const expected = new Set([...item.expected.rules, ...item.expected.alternatives]);
  const hits = diagnostics.filter(diagnostic => expected.has(diagnostic.ruleId));
  if (hits.length > 0) {
    const spanOk = hits.some(diagnostic => diagnostic.locations[0]?.pointer === item.expected.evidencePointer);
    return {
      caseId: item.caseId,
      family: item.family,
      split: item.split,
      outcome: "hit",
      signalRules: diagnostics.map(diagnostic => diagnostic.ruleId),
      spanOk,
    };
  }
  const expectedObservations = item.expected.rules.map(observation).filter(entry => entry !== undefined);
  const unknown = expectedObservations.some(entry => ["inconclusive", "not_applicable", "not_run", "malformed", "backend_error"].includes(entry.status));
  return {
    caseId: item.caseId,
    family: item.family,
    split: item.split,
    outcome: unknown ? "unknown" : "miss",
    signalRules: diagnostics.map(diagnostic => diagnostic.ruleId),
  };
};

const metric = subset => {
  const rules = ["QSM001", "QSM002", "QSM003", "QSM004", "QBE004"];
  const perRule = Object.fromEntries(rules.map(rule => [rule, { tp: 0, fn: 0, unknown: 0, fp: 0 }]));
  let stoppedLegitimate = 0;
  let legitimate = 0;
  let hits = 0;
  let spanOk = 0;
  for (const item of subset) {
    const diagnostics = item.report.diagnostics;
    if (item.kind === "legitimate") {
      legitimate += 1;
      if (diagnostics.length > 0) stoppedLegitimate += 1;
      for (const diagnostic of diagnostics) {
        if (perRule[diagnostic.ruleId]) perRule[diagnostic.ruleId].fp += 1;
      }
      continue;
    }
    const expected = new Set([...item.expected.rules, ...item.expected.alternatives]);
    const hit = diagnostics.filter(diagnostic => expected.has(diagnostic.ruleId));
    const outcome = item.outcome;
    for (const rule of item.expected.rules) {
      if (!perRule[rule]) continue;
      if (outcome === "hit") perRule[rule].tp += 1;
      else if (outcome === "unknown") perRule[rule].unknown += 1;
      else perRule[rule].fn += 1;
    }
    for (const diagnostic of diagnostics) {
      if (expected.has(diagnostic.ruleId)) continue;
      if (perRule[diagnostic.ruleId]) perRule[diagnostic.ruleId].fp += 1;
    }
    if (hit.length > 0) {
      hits += 1;
      if (hit.some(diagnostic => diagnostic.locations[0]?.pointer === item.expected.evidencePointer)) spanOk += 1;
    }
  }
  return {
    perRule,
    legitimateStopRate: legitimate === 0 ? null : stoppedLegitimate / legitimate,
    evidenceSpanCorrectness: hits === 0 ? null : spanOk / hits,
    defectHits: subset.filter(item => item.kind === "defect" && item.outcome === "hit").length,
    defectUnknown: subset.filter(item => item.kind === "defect" && item.outcome === "unknown").length,
    defectMisses: subset.filter(item => item.kind === "defect" && item.outcome === "miss").length,
  };
};

const run = async () => {
  const detailed = [];
  let usage = null;
  let failures = 0;

  if (values.live) {
    const providerCredential = process.env.TYPESAFE_CREDENTIAL_ENV;
    if (providerCredential === undefined || providerCredential === "") {
      console.error("live mode requires TYPESAFE_CREDENTIAL_ENV in the environment (the key is never written to disk)");
      process.exit(2);
    }
    const transport = createHttpTransport({ providerCredential });
    const recordings = [];
    usage = { requests: 0, inputTokens: 0, outputTokens: 0, latencyMs: 0 };
    for (const item of cases) {
      const outcome = await screenLive(item.suite, pack, transport, version, {
        maxRequests: 1,
        ...(values.model === undefined ? {} : { model: values.model }),
        onRecord: recording => recordings.push(recording),
      });
      failures += outcome.failures.length;
      if (outcome.report.usage) {
        usage.requests += outcome.report.usage.requests;
        usage.inputTokens += outcome.report.usage.inputTokens;
        usage.outputTokens += outcome.report.usage.outputTokens;
        usage.latencyMs += outcome.report.usage.latencyMs;
      }
      detailed.push({ ...item, report: outcome.report, ...classifyCase(item, outcome.report) });
    }
    writeFileSync(values.record, recordings.map(recording => JSON.stringify(recording)).join("\n") + (recordings.length === 0 ? "" : "\n"), { mode: 0o600 });
  } else {
    if (values.replay === undefined) {
      console.error("usage: node evaluation/run-corpus.mjs --live | --replay <recorded.jsonl>");
      process.exit(2);
    }
    const byDigest = new Map();
    for (const line of readFileSync(values.replay, "utf8").split("\n")) {
      if (line.trim() === "") continue;
      const recording = JSON.parse(line);
      byDigest.set(recording.requestDigest, recording);
    }
    for (const item of cases) {
      const requests = buildScreeningRequests(item.suite, pack);
      const recordingsForCase = requests
        .map(request => byDigest.get(request.requestDigest))
        .filter(recording => recording !== undefined);
      const report = screenFromRecordings(item.suite, pack, recordingsForCase, version);
      detailed.push({ ...item, report, ...classifyCase(item, report) });
    }
  }

  const subset = split => detailed.filter(item => item.split === split);
  const metrics = {
    corpus: {
      total: detailed.length,
      defect: detailed.filter(item => item.kind === "defect").length,
      legitimate: detailed.filter(item => item.kind === "legitimate").length,
    },
    overall: metric(detailed),
    tuning: metric(subset("tuning")),
    eval: metric(subset("eval")),
    eval2: subset("eval2").length === 0 ? null : metric(subset("eval2")),
  };
  const result = {
    mode: values.live ? "live" : "replay",
    model: values.model ?? pack.model ?? "jev-latest",
    ruleSetDigest: detailed[0]?.report.ruleSetDigest ?? null,
    policy: detailed[0]?.report.policy ?? null,
    metrics,
    usage,
    backendFailures: failures,
    cases: detailed.map(item => ({
      caseId: item.caseId,
      family: item.family,
      kind: item.kind,
      split: item.split,
      outcome: item.outcome,
      signalRules: item.signalRules,
      spanOk: item.spanOk ?? null,
      diagnostics: item.report.diagnostics.length,
    })),
  };
  writeFileSync(values.out, JSON.stringify(result, null, 2) + "\n");

  const print = (label, value) => {
    console.log(`${label}: hits ${value.defectHits}, unknown ${value.defectUnknown}, misses ${value.defectMisses}, legitimate-stop ${value.legitimateStopRate === null ? "n/a" : `${Math.round(value.legitimateStopRate * 100)}%`}, span ${value.evidenceSpanCorrectness === null ? "n/a" : `${Math.round(value.evidenceSpanCorrectness * 100)}%`}`);
    for (const [rule, counts] of Object.entries(value.perRule)) {
      console.log(`  ${rule}: tp ${counts.tp}, unknown ${counts.unknown}, fn ${counts.fn}, fp ${counts.fp}`);
    }
  };
  console.log(`screening corpus (${values.live ? "live" : "replay"}), model ${result.model}`);
  if (usage) console.log(`usage: ${usage.requests} requests, ${usage.inputTokens} input tokens, ${usage.outputTokens} output tokens, ${usage.latencyMs} ms, failures ${failures}`);
  print("overall", metrics.overall);
  print("tuning", metrics.tuning);
  print("eval", metrics.eval);
  if (metrics.eval2 !== null) print("eval2", metrics.eval2);
  console.log(`wrote ${values.out}`);
};

await run();

state.screening_ts:
/**
 * Semantic screening: builds small meta-questions about each QuestionSpec and
 * turns validated Noul answers into model_signal diagnostics.
 *
 * The model never sees state values, expected diagnostics, or rule
 * thresholds: the sent state contains the question text and field descriptors
 * only. Diagnostics are assembled here from the rule pack, so a candidate
 * answer cannot change severity, rule identity, or output shape.
 *
 * Two execution modes share one classifier:
 * - screenFromRecordings: recorded responses (offline, deterministic)
 * - screenLive: an injected transport (the only network path in the bundle)
 */
import { parseNoulAnswer, parseSystemOneResponse } from "./adapter.js";
import type {
  Diagnostic,
  Json,
  QuestionSpec,
  QuestionSuite,
  RecordedResponse,
  ScreeningObservation,
  ScreeningPack,
  ScreeningPolicy,
  ScreeningReport,
  ScreeningRequest,
  ScreeningRuleDefinition,
  ScreeningRuleView,
  ScreeningSubQuestion,
  ScreeningUsage,
} from "./contracts.js";
import { digestOf } from "./digest.js";
import type { BackendFailure, SystemOneTransport } from "./transport.js";

export class ScreeningError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ScreeningError";
  }
}

export const SCREENING_POLICY: ScreeningPolicy = {
  policyId: "screening-reference-v0.1",
  applicabilityAtLeast: 0.8,
  sufficiencyAtLeast: 0.8,
  signalAtLeast: 0.5,
  note: "Uncalibrated defaults for the reference implementation. Choose thresholds on validation data before relying on them; a signal is a model_signal, not a verdict.",
};

export function ruleApplies(rule: ScreeningRuleDefinition, question: QuestionSpec): boolean {
  const { modes, outputKinds } = rule.appliesTo;
  if (modes !== undefined && !modes.includes(question.mode)) return false;
  if (outputKinds !== undefined && !outputKinds.includes(question.output.kind)) return false;
  return true;
}

function describeOutput(output: QuestionSpec["output"]): Json {
  if (output.kind === "boolean") {
    return { kind: "boolean", criteria: { true: output.criteria.true, false: output.criteria.false } };
  }
  if (output.kind === "categorical") {
    return {
      kind: "categorical",
      selection: output.selection,
      options: output.options.map(option => ({ id: option.id, description: option.description })),
      ...(output.fallbackOptionId === undefined ? {} : { fallbackOptionId: output.fallbackOptionId }),
      ...(output.tieBreak === undefined ? {} : { tieBreak: output.tieBreak }),
    };
  }
  return {
    kind: "ordinal",
    axis: output.axis,
    levels: output.levels.map(level => ({ id: level.id, description: level.description })),
  };
}

function describeField(suite: QuestionSuite, fieldId: string): Json {
  const field = suite.state.fields.find(candidate => candidate.id === fieldId);
  if (!field) throw new ScreeningError(`question references unknown field ${fieldId}`);
  return {
    fieldId: field.id,
    pointer: field.pointer,
    valueType: field.valueType,
    nullable: field.nullable,
    role: field.role,
  };
}

function subQuestion(definition: { instructions: string; criteria: { true: string; false: string } }): ScreeningSubQuestion {
  return { type: "noul", instructions: definition.instructions, criteria: definition.criteria };
}

export function buildScreeningRequests(suite: QuestionSuite, pack: ScreeningPack): ScreeningRequest[] {
  const model = pack.model ?? "jev-latest";
  const requests: ScreeningRequest[] = [];
  suite.questions.forEach((question, questionIndex) => {
    const rules = pack.rules.filter(rule => ruleApplies(rule, question));
    if (rules.length === 0) return;
    const state: Json = {
      question: {
        instructions: question.instructions,
        mode: question.mode,
        applicability: question.applicability,
        evidenceBoundary: question.evidenceBoundary,
        output: describeOutput(question.output),
        inputs: question.inputs.map(fieldId => describeField(suite, fieldId)),
        policyRefs: question.policyRefs.map(fieldId => describeField(suite, fieldId)),
      },
    };
    const questions: Record<string, ScreeningSubQuestion> = {};
    const ruleViews: ScreeningRuleView[] = [];
    for (const rule of rules) {
      const subQuestionIds = {
        applicability: `${rule.id}__applicability`,
        sufficiency: `${rule.id}__sufficiency`,
        violation: `${rule.id}__violation`,
      };
      questions[subQuestionIds.applicability] = subQuestion(rule.applicability);
      questions[subQuestionIds.sufficiency] = subQuestion(rule.sufficiency);
      questions[subQuestionIds.violation] = subQuestion(rule.violation);
      ruleViews.push({ ruleId: rule.id, summary: rule.summary, subQuestionIds });
    }
    requests.push({
      questionId: question.id,
      questionIndex,
      state,
      questions,
      rules: ruleViews,
      requestDigest: digestOf({ model, state, questions }),
    });
  });
  return requests;
}

interface Classification {
  observations: ScreeningObservation[];
  diagnostics: Diagnostic[];
  usage?: { inputTokens?: number; outputTokens?: number };
}

function classifyResponse(
  request: ScreeningRequest,
  response: Json,
  pack: ScreeningPack,
  policy: ScreeningPolicy,
): Classification {
  const expectedIds = request.rules.flatMap(rule => [
    rule.subQuestionIds.applicability,
    rule.subQuestionIds.sufficiency,
    rule.subQuestionIds.violation,
  ]);
  const envelope = parseSystemOneResponse(response, expectedIds);
  if (!envelope.ok) {
    const problems = envelope.issues.map(issue => `${issue.path} ${issue.message}`);
    return {
      observations: request.rules.map(rule => ({
        questionId: request.questionId,
        ruleId: rule.ruleId,
        status: "malformed" as const,
        problems,
      })),
      diagnostics: [],
    };
  }
  const observations: ScreeningObservation[] = [];
  const diagnostics: Diagnostic[] = [];
  for (const rule of request.rules) {
    const parsed = {
      applicability: parseNoulAnswer(envelope.value.answers[rule.subQuestionIds.applicability]),
      sufficiency: parseNoulAnswer(envelope.value.answers[rule.subQuestionIds.sufficiency]),
      violation: parseNoulAnswer(envelope.value.answers[rule.subQuestionIds.violation]),
    };
    const failed = Object.entries(parsed).filter(entry => !entry[1].ok);
    if (failed.length > 0) {
      const problems = failed.flatMap(([dimension, result]) => result.ok
        ? []
        : result.issues.map(issue => `${dimension}${issue.path} ${issue.message}`));
      observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "malformed", problems });
      continue;
    }
    const applicability = parsed.applicability.ok ? parsed.applicability.value.noul : 0;
    const sufficiency = parsed.sufficiency.ok ? parsed.sufficiency.value.noul : 0;
    const violation = parsed.violation.ok ? parsed.violation.value.noul : 0;
    const probabilities = { applicability, sufficiency, violation };
    if (applicability < policy.applicabilityAtLeast) {
      observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "not_applicable", ...probabilities });
      continue;
    }
    if (sufficiency < policy.sufficiencyAtLeast) {
      observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "inconclusive", ...probabilities });
      continue;
    }
    if (violation >= policy.signalAtLeast) {
      observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "signal", ...probabilities });
      const definition = pack.rules.find(candidate => candidate.id === rule.ruleId);
      diagnostics.push({
        ruleId: rule.ruleId,
        questionId: request.questionId,
        severity: "warning",
        basis: "model_signal",
        message: definition?.message ?? rule.summary,
        locations: [{ pointer: `/questions/${request.questionIndex}${definition?.evidencePath ?? "/instructions"}` }],
        evidence: [
          { kind: "model_response", runId: request.requestDigest, answerId: rule.subQuestionIds.applicability, modelProbability: applicability },
          { kind: "model_response", runId: request.requestDigest, answerId: rule.subQuestionIds.sufficiency, modelProbability: sufficiency },
          { kind: "model_response", runId: request.requestDigest, answerId: rule.subQuestionIds.violation, modelProbability: violation },
        ],
      });
      continue;
    }
    observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "no_signal", ...probabilities });
  }
  return { observations, diagnostics, usage: envelope.value.usage };
}

function assembleReport(input: {
  suite: QuestionSuite;
  requests: ScreeningRequest[];
  observations: ScreeningObservation[];
  diagnostics: Diagnostic[];
  version: string;
  policy: ScreeningPolicy;
  provider: ScreeningReport["provider"];
  ruleSetDigest: string;
  model?: string;
  usage?: ScreeningUsage;
  extraNotExecuted?: string[];
}): ScreeningReport {
  const { suite, requests, observations, diagnostics, version, policy, provider, ruleSetDigest, model, usage, extraNotExecuted } = input;
  const count = (status: ScreeningObservation["status"]): number => observations.filter(observation => observation.status === status).length;
  const withoutDigest = {
    schemaVersion: "0.1" as const,
    kind: "qlint.screening-report" as const,
    tool: { name: "qlint" as const, version },
    provider,
    ...(model === undefined ? {} : { model }),
    ...(usage === undefined ? {} : { usage }),
    suite: { id: suite.id, digest: digestOf(suite) },
    ruleSetDigest,
    policy,
    observations,
    diagnostics,
    summary: {
      questions: suite.questions.length,
      requests: requests.length,
      signals: count("signal"),
      inconclusive: count("inconclusive"),
      notRun: count("not_run"),
      malformed: count("malformed"),
      backendErrors: count("backend_error"),
    },
    notExecuted: [
      ...(extraNotExecuted ?? []),
      "threshold calibration",
      "policy excerpts (policyRefs values are not sent, only their descriptors)",
      "suite statistics",
    ],
  };
  return { ...withoutDigest, digest: digestOf(withoutDigest) };
}

export function screeningReportDigest(report: ScreeningReport): string {
  const { digest: _digest, ...rest } = report;
  return digestOf(rest);
}

export function screenFromRecordings(
  suite: QuestionSuite,
  pack: ScreeningPack,
  recordings: RecordedResponse[],
  version: string,
  policy: ScreeningPolicy = SCREENING_POLICY,
): ScreeningReport {
  const requests = buildScreeningRequests(suite, pack);
  const byDigest = new Map<string, Json>();
  for (const recording of recordings) {
    if (byDigest.has(recording.requestDigest)) {
      throw new ScreeningError(`duplicate recorded response for ${recording.requestDigest}`);
    }
    byDigest.set(recording.requestDigest, recording.response);
  }

  const observations: ScreeningObservation[] = [];
  const diagnostics: Diagnostic[] = [];
  for (const request of requests) {
    const response = byDigest.get(request.requestDigest);
    if (response === undefined) {
      for (const rule of request.rules) {
        observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "not_run" });
      }
      continue;
    }
    const classified = classifyResponse(request, response, pack, policy);
    observations.push(...classified.observations);
    diagnostics.push(...classified.diagnostics);
  }
  return assembleReport({
    suite, requests, observations, diagnostics, version, policy, provider: "replay",
    ruleSetDigest: digestOf(pack.rules),
    extraNotExecuted: ["provider execution (replay only; no network)"],
  });
}

export interface LiveScreeningOptions {
  policy?: ScreeningPolicy;
  /** Requests beyond the budget are recorded as not_run. */
  maxRequests?: number;
  /** Overrides the pack's model name; the request digest binds the model. */
  model?: string;
  onRecord?: (recording: RecordedResponse) => void;
}

export interface LiveScreeningFailure {
  requestDigest: string;
  questionId: string;
  failure: BackendFailure;
}

export interface LiveScreeningOutcome {
  report: ScreeningReport;
  failures: LiveScreeningFailure[];
}

export async function screenLive(
  suite: QuestionSuite,
  pack: ScreeningPack,
  transport: SystemOneTransport,
  version: string,
  options: LiveScreeningOptions = {},
): Promise<LiveScreeningOutcome> {
  const policy = options.policy ?? SCREENING_POLICY;
  const effectivePack = options.model === undefined ? pack : { ...pack, model: options.model };
  const requests = buildScreeningRequests(suite, effectivePack);
  const model = effectivePack.model ?? "jev-latest";
  const budget = options.maxRequests ?? requests.length;

  const observations: ScreeningObservation[] = [];
  const diagnostics: Diagnostic[] = [];
  const failures: LiveScreeningFailure[] = [];
  let requestsSent = 0;
  let inputTokens = 0;
  let outputTokens = 0;
  let latencyMs = 0;

  for (let index = 0; index < requests.length; index += 1) {
    const request = requests[index]!;
    if (index >= budget) {
      for (const rule of request.rules) {
        observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "not_run" });
      }
      continue;
    }
    requestsSent += 1;
    const result = await transport.send({
      model,
      state: request.state,
      questions: request.questions as unknown as Record<string, Json>,
    });
    latencyMs += result.latencyMs;
    if (!result.ok) {
      failures.push({ requestDigest: request.requestDigest, questionId: request.questionId, failure: result.failure });
      for (const rule of request.rules) {
        observations.push({
          questionId: request.questionId,
          ruleId: rule.ruleId,
          status: "backend_error",
          problems: [`${result.failure.kind}: ${result.failure.message}`],
        });
      }
      continue;
    }
    options.onRecord?.({ requestDigest: request.requestDigest, response: result.response });
    const classified = classifyResponse(request, result.response, effectivePack, policy);
    observations.push(...classified.observations);
    diagnostics.push(...classified.diagnostics);
    inputTokens += classified.usage?.inputTokens ?? 0;
    outputTokens += classified.usage?.outputTokens ?? 0;
  }

  const budgetNote = budget < requests.length
    ? `budget: ${budget} of ${requests.length} requests executed; the rest are not_run`
    : undefined;
  const report = assembleReport({
    suite,
    requests,
    observations,
    diagnostics,
    version,
    policy,
    provider: "typesafe",
    ruleSetDigest: digestOf(pack.rules),
    model,
    usage: { requests: requestsSent, inputTokens, outputTokens, latencyMs },
    extraNotExecuted: [
      "provider execution: live requests were sent to the TypeSafe endpoint",
      ...(budgetNote === undefined ? [] : [budgetNote]),
    ],
  });
  return { report, failures };
}

