/** qlint contract proposal v0.1. Provider-neutral; no model or network dependency. */
export type Id = string;
export type JsonPrimitive = string | number | boolean | null;
export type Json = JsonPrimitive | Json[] | { [key: string]: Json };

export interface StageSpec {
  id: Id;
  /** Prerequisite stages; forms a DAG, not a total ordering. */
  after: Id[];
}
export interface FieldSpec {
  id: Id;
  /** Non-root JSON Pointer into an immutable, time-bounded snapshot. */
  pointer: string;
  valueType: "string" | "number" | "integer" | "boolean" | "array" | "object";
  nullable: boolean;
  availableFrom: Id;
  role: "evidence" | "policy" | "target" | "metadata";
  derivedFrom: Id[];
  sensitivity: "public" | "internal" | "restricted";
}
export interface StateContract {
  id: Id;
  stages: StageSpec[];
  fields: FieldSpec[];
}
export interface OptionSpec { id: Id; description: string }
export type OutputSpec =
  | { kind: "boolean"; criteria: { true: string; false: string } }
  | {
      kind: "categorical";
      selection: "partition" | "best_fit";
      options: OptionSpec[];
      /** A real content category, not the same thing as missing evidence. */
      fallbackOptionId?: Id;
      /** Natural-language tie resolution; screened, not statically proven. */
      tieBreak?: string;
    }
  | {
      kind: "ordinal";
      axis: string;
      /** List order is ascending; each description must be self-contained. */
      levels: OptionSpec[];
    };
export interface QuestionSpec {
  id: Id;
  revision: number;
  mode: "extract" | "interpret" | "predict";
  instructions: string;
  /** Every listed field is required for this v0.1 contract. */
  inputs: Id[];
  /** Kept orthogonal to mode; policy documents are also projected inputs. */
  policyRefs: Id[];
  applicability: string;
  /** Define what counts as evidence, including negative evidence. */
  evidenceBoundary: string;
  missingInput: "abstain";
  insufficientEvidence: "abstain";
  /** Metadata only; its actual value MUST NOT enter a prediction payload. */
  prediction?: { targetRef: Id; horizon: string };
  output: OutputSpec;
}
export interface GateSpec {
  purpose: "applicability" | "evidence";
  questionId: Id;
  /** p <= falseAtMost: false; p >= trueAtLeast: true; otherwise undecided. */
  falseAtMost: number;
  trueAtLeast: number;
}
export interface BindingSpec {
  questionId: Id;
  atStage: Id;
  profile: "feature" | "monitor" | "router" | "judge";
  gates: GateSpec[];
  onIndeterminate: "abstain";
}
export interface QuestionSuite {
  schemaVersion: "0.1";
  id: Id;
  state: StateContract;
  questions: QuestionSpec[];
  /** v0.1: exactly one binding per question in an executable suite. */
  bindings: BindingSpec[];
}

export interface PlanFieldProjection {
  fieldId: Id;
  pointer: string;
  valueType: FieldSpec["valueType"];
  nullable: boolean;
  /** Targets are never projected; the type excludes that role. */
  role: "evidence" | "policy" | "metadata";
  sensitivity: FieldSpec["sensitivity"];
  /** Redaction happens at the value boundary; the plan records the intent. */
  handling: "verbatim";
}
export interface PlanGate {
  purpose: GateSpec["purpose"];
  questionId: Id;
}
export interface PlanQuestion {
  questionId: Id;
  atStage: Id;
  profile: BindingSpec["profile"];
  mode: QuestionSpec["mode"];
  outputKind: OutputSpec["kind"];
  gates: PlanGate[];
  inputs: PlanFieldProjection[];
  /** Approved policy documents travel separately from evidence inputs. */
  policyRefs: PlanFieldProjection[];
  redaction: {
    policy: "explicit-projection-v0.1";
    excludedFieldIds: Id[];
    restrictedFieldIds: Id[];
    note: string;
  };
  limits: {
    maxBytes?: number;
    maxTokens?: number;
    rationale: string;
  };
}
/** Immutable, digest-bound execution plan produced by `qlint inspect`. */
export interface ExecutionPlan {
  schemaVersion: "0.1";
  kind: "qlint.execution-plan";
  tool: { name: "qlint"; version: string };
  provider: { name: "replay"; network: false };
  suite: { id: Id; digest: string };
  questions: PlanQuestion[];
  requestCount: number;
  maxRequests: number;
  notes: string[];
  /** sha256 over the plan content without this field. */
  digest: string;
}
export interface ProjectedPayload {
  questionId: Id;
  atStage: Id;
  inputs: Record<Id, Json>;
  policyRefs: Record<Id, Json>;
}
export interface ProjectionProblem {
  fieldId: Id;
  kind: "type_mismatch" | "target_role" | "unknown_field";
  message: string;
}
export type ProjectionOutcome =
  | { status: "projected"; payload: ProjectedPayload; requestDigest: string }
  | { status: "abstained"; reason: "missing_input" | "null_value"; fieldIds: Id[] }
  | { status: "invalid"; problems: ProjectionProblem[] };
export interface RecordedResponse {
  requestDigest: string;
  /** The raw provider response, kept opaque in this bundle. */
  response: Json;
}
export interface ReplayResult {
  caseId: Id;
  questionId: Id;
  status: "replayed" | "abstained" | "invalid" | "not_run";
  requestDigest?: string;
  payload?: ProjectedPayload;
  response?: Json;
  reason?: string;
  problems?: ProjectionProblem[];
}
export interface RunReport {
  schemaVersion: "0.1";
  kind: "qlint.run-report";
  mode: "replay";
  tool: { name: "qlint"; version: string };
  planDigest: string;
  suite: { id: Id; digest: string };
  results: ReplayResult[];
  summary: {
    cases: number;
    questions: number;
    replayed: number;
    abstained: number;
    invalid: number;
    notRun: number;
    requestsSent: number;
  };
  notExecuted: string[];
  /** sha256 over the report content without this field. */
  digest: string;
}
export interface ScreeningPolicy {
  policyId: Id;
  /** Uncalibrated defaults; choose thresholds on validation data before relying on them. */
  applicabilityAtLeast: number;
  sufficiencyAtLeast: number;
  signalAtLeast: number;
  note: string;
}
export interface ScreeningSubQuestion {
  type: "noul";
  instructions: string;
  criteria: { true: string; false: string };
}
export interface ScreeningRuleView {
  ruleId: Id;
  summary: string;
  subQuestionIds: { applicability: string; sufficiency: string; violation: string };
}
export interface ScreeningRequest {
  questionId: Id;
  questionIndex: number;
  /** Content that would be sent as provider state. Never contains field values. */
  state: Json;
  /** Content that would be sent as provider questions, keyed by sub-question id. */
  questions: Record<string, ScreeningSubQuestion>;
  rules: ScreeningRuleView[];
  requestDigest: string;
}
export interface ScreeningObservation {
  questionId: Id;
  ruleId: Id;
  status: "signal" | "no_signal" | "not_applicable" | "inconclusive" | "malformed" | "backend_error" | "not_run";
  applicability?: number;
  sufficiency?: number;
  violation?: number;
  problems?: string[];
}
export interface ScreeningUsage {
  requests: number;
  inputTokens: number;
  outputTokens: number;
  latencyMs: number;
}
export interface ScreeningReport {
  schemaVersion: "0.1";
  kind: "qlint.screening-report";
  tool: { name: "qlint"; version: string };
  provider: "replay" | "typesafe";
  model?: string;
  usage?: ScreeningUsage;
  suite: { id: Id; digest: string };
  /** Content digest of the rule pack that built the diagnostics. */
  ruleSetDigest: string;
  policy: ScreeningPolicy;
  observations: ScreeningObservation[];
  /** model_signal diagnostics only; the rule engine builds them, never the model. */
  diagnostics: Diagnostic[];
  summary: {
    questions: number;
    requests: number;
    signals: number;
    inconclusive: number;
    notRun: number;
    malformed: number;
    backendErrors: number;
  };
  notExecuted: string[];
  digest: string;
}
export interface ScreeningRuleDefinition {
  id: Id;
  summary: string;
  message: string;
  /** JSON Pointer suffix inside the question that the diagnostic points at. */
  evidencePath?: string;
  appliesTo: {
    modes?: QuestionSpec["mode"][];
    outputKinds?: OutputSpec["kind"][];
  };
  applicability: { instructions: string; criteria: { true: string; false: string } };
  sufficiency: { instructions: string; criteria: { true: string; false: string } };
  violation: { instructions: string; criteria: { true: string; false: string } };
}
export interface ScreeningPack {
  schemaVersion: "0.1";
  note: string;
  model?: string;
  rules: ScreeningRuleDefinition[];
}
export type DiagnosticBasis = "static_proof" | "model_signal" | "empirical_witness";
export type Severity = "error" | "warning" | "info";
export type Evidence =
  | { kind: "contract_ref"; pointer: string }
  | { kind: "model_response"; runId: Id; answerId: Id; modelProbability?: number }
  | {
      kind: "paired_case";
      beforeCaseId: Id;
      afterCaseId: Id;
      transformId: Id;
      transformReview: "human_reviewed" | "unreviewed";
    }
  | { kind: "metric"; name: string; value: number; sampleSize: number; unit: string };
/**
 * A reported location. `pointer` always refers to the input document.
 * CLI tools add `file`/`line`/`column` after resolving the pointer against
 * the original text; `line` and `column` are 1-based. Library callers that
 * never see source text leave them absent.
 */
export interface DiagnosticLocation {
  pointer: string;
  file?: string;
  line?: number;
  column?: number;
}
export interface Diagnostic {
  ruleId: string;
  questionId?: Id;
  severity: Severity;
  basis: DiagnosticBasis;
  message: string;
  locations: DiagnosticLocation[];
  evidence: Evidence[];
}
export interface CheckCoverage {
  ruleId: string;
  status: "passed" | "flagged" | "unknown" | "not_run" | "not_applicable";
}
export interface Assessment {
  questionId: Id;
  status: "invalid" | "review_required" | "screened" | "inconclusive";
  coverage: CheckCoverage[];
  diagnostics: Diagnostic[];
  /** An explicit profile, not a universal correctness certificate. */
  profileId: Id;
}
export type ProbabilitySource =
  | "model_distribution"
  | "empirical_frequency"
  | "self_report";
export type Measurement =
  | { kind: "boolean"; representation: "distribution"; pTrue: number; probabilitySource: ProbabilitySource }
  | { kind: "boolean"; representation: "label"; value: boolean }
  | {
      kind: "categorical" | "ordinal";
      representation: "distribution";
      /** Stable option/level IDs; never silently key by presentation order. */
      distribution: Record<Id, number>;
      probabilitySource: ProbabilitySource;
    }
  | { kind: "categorical" | "ordinal"; representation: "label"; labelId: Id };
export interface RunProvenance {
  runId: Id;
  provider: string;
  requestedModel: string;
  resolvedModel?: string;
  providerRevision?: string;
  adapterVersion: string;
  specDigest: string;
  projectedStateDigest: string;
  ruleSetDigest: string;
  calibrationId?: string;
}
export type EvaluationResult =
  | { status: "answered"; measurement: Measurement; provenance: RunProvenance }
  | {
      status: "abstained";
      reason: "missing_input" | "insufficient_evidence" | "gate_uncertain";
      evidenceRefs: string[];
      provenance?: RunProvenance;
    }
  | { status: "not_applicable"; gateQuestionId: Id; provenance?: RunProvenance }
  | { status: "error"; code: string; message: string; retryable: boolean };
export interface BackendCapabilities {
  kinds: OutputSpec["kind"][];
  nativeDistribution: boolean;
  nativeAbstention: boolean;
  maxCategoricalOptions?: number;
  maxOrdinalLevels?: number;
  /** A declaration to be checked by adapter conformance tests. */
  questionIdsVisibleToModel?: boolean;
  siblingLevelDescriptionsVisible?: boolean;
}
export interface StaticReport {
  scope: "reference_static_checks_only";
  diagnostics: Diagnostic[];
  executedRuleIds: string[];
  notExecuted: string[];
}

/** A model can emit signals, never an authoritative Diagnostic or CI policy. */
export interface ModelScreenSignal {
  ruleId: string;
  questionId: Id;
  applicability: "applicable" | "not_applicable" | "unknown";
  evidenceSufficiency: "sufficient" | "insufficient" | "unknown";
  violation: Measurement;
  /** IDs must refer to fragments supplied by the parser; no invented quotes. */
  fragmentIds: Id[];
  provenance: RunProvenance;
}

state.validate_cases_mjs:
/**
 * Validates the evaluation corpus offline:
 * counts, splits, unique ids, lint-clean suites, and that the expected rule
 * actually applies to the case's question. No model calls.
 *
 * Exported as validateCases() for tests; also runnable directly.
 */
import { readFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
import { createSchemaValidators, loadSchemaSync } from "../dist/schema-validation.js";
import { lintSuiteSource } from "../dist/lint-suite.js";
import { ruleApplies } from "../dist/screening.js";

const root = new URL("../", import.meta.url);
const validators = createSchemaValidators({
  suite: loadSchemaSync(new URL("schemas/question-suite.schema.json", root)),
  diagnostic: loadSchemaSync(new URL("schemas/diagnostic.schema.json", root)),
  executionPlan: loadSchemaSync(new URL("schemas/execution-plan.schema.json", root)),
});
const catalog = JSON.parse(readFileSync(new URL("rules/catalog.json", root), "utf8"));
const pack = JSON.parse(readFileSync(new URL("rules/screening-pack.json", root), "utf8"));
const familyRule = new Map(pack.rules.map(rule => [rule.id, rule]));

export function validateCases(cases) {
  const problems = [];
  const check = (condition, message) => {
    if (!condition) problems.push(message);
  };

  check(cases.length === 80, `expected 80 cases, found ${cases.length}`);
  const defect = cases.filter(item => item.kind === "defect");
  const legitimate = cases.filter(item => item.kind === "legitimate");
  check(defect.length === 55, `expected 55 defect cases, found ${defect.length}`);
  check(legitimate.length === 25, `expected 25 legitimate cases, found ${legitimate.length}`);
  check(cases.filter(item => item.split === "tuning").length === 30, "expected 30 tuning cases");
  check(cases.filter(item => item.split === "eval").length === 30, "expected 30 eval cases");
  check(cases.filter(item => item.split === "eval2").length === 20, "expected 20 eval2 cases");

  const ids = new Set();
  for (const item of cases) {
    check(typeof item.caseId === "string" && item.caseId !== "", "caseId must be a non-empty string");
    check(!ids.has(item.caseId), `duplicate caseId ${item.caseId}`);
    ids.add(item.caseId);
    check(["ja", "en"].includes(item.language), `${item.caseId}: language must be ja or en`);
    check(["tuning", "eval", "eval2"].includes(item.split), `${item.caseId}: split must be tuning, eval, or eval2`);
    check(["QSM001", "QSM002", "QSM003", "QSM004", "QBE004"].includes(item.family), `${item.caseId}: unknown family ${item.family}`);
    check(typeof item.groupId === "string" && item.groupId !== "", `${item.caseId}: groupId is required`);

    if (item.kind === "defect") {
      check(item.expected.status === "signal", `${item.caseId}: defect expects signal`);
      check(Array.isArray(item.expected.rules) && item.expected.rules.includes(item.family), `${item.caseId}: expected rules must name the family`);
      check(/^\/questions\/0\/(instructions|output)$/.test(item.expected.evidencePointer), `${item.caseId}: evidencePointer must target instructions or output`);
      const rule = familyRule.get(item.family);
      check(rule !== undefined, `${item.caseId}: family has no screening rule`);
      if (rule) check(ruleApplies(rule, item.suite.questions[0]), `${item.caseId}: expected rule ${item.family} does not apply to this question`);
    } else {
      check(item.expected.status === "no_signal", `${item.caseId}: legitimate expects no_signal`);
      check(item.expected.rules.length === 0, `${item.caseId}: legitimate expects no rules`);
    }

    const source = JSON.stringify(item.suite);
    const lint = lintSuiteSource({
      source,
      file: `${item.caseId}.json`,
      catalogRuleIds: catalog.rules.map(rule => rule.id),
      validators,
      version: "corpus-check",
    });
    check(lint.summary.errors === 0, `${item.caseId}: suite has lint errors: ${lint.diagnostics.map(d => d.message).join("; ")}`);
  }
  return problems;
}

export function loadCases() {
  const text = readFileSync(new URL("cases.jsonl", import.meta.url), "utf8");
  return text.split("\n").filter(line => line.trim() !== "").map(line => JSON.parse(line));
}

const isMain = process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  const problems = validateCases(loadCases());
  if (problems.length > 0) {
    for (const problem of problems) console.error(`case validation: ${problem}`);
    process.exitCode = 1;
  } else {
    console.log("evaluation corpus: 80 cases valid (55 defect / 25 legitimate; 30 tuning / 30 eval / 20 eval2)");
  }
}

state.evaluation_test_mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { loadCases, validateCases } from '../evaluation/validate-cases.mjs';

test('the evaluation corpus is complete, split, and lint-clean', () => {
  const cases = loadCases();
  assert.deepEqual(validateCases(cases), []);
  assert.equal(cases.length, 80);
  assert.equal(cases.filter(item => item.kind === 'defect').length, 55);
  assert.equal(cases.filter(item => item.kind === 'legitimate').length, 25);
  assert.equal(cases.filter(item => item.split === 'tuning').length, 30);
  assert.equal(cases.filter(item => item.split === 'eval').length, 30);
  assert.equal(cases.filter(item => item.split === 'eval2').length, 20);
});

test('base-corpus paraphrase groups bundle more than one case', () => {
  const groups = new Map();
  for (const item of loadCases().filter(entry => entry.split === 'tuning' || entry.split === 'eval')) {
    groups.set(item.groupId, (groups.get(item.groupId) ?? 0) + 1);
  }
  const singletons = [...groups.entries()].filter(([, count]) => count < 2);
  assert.deepEqual(singletons, []);
});
